-- migrate:statement
-- Persist the abilities previously granted by built-in role names. Custom roles receive no implicit privileges.
UPDATE crm_role SET perms=(SELECT jsonb_agg(DISTINCT value) FROM jsonb_array_elements(COALESCE(perms,'[]'::jsonb) || '["crm:*:full"]'::jsonb)) WHERE code='admin' AND deleted_at IS NULL;
-- migrate:statement
